#!/usr/bin/env node
// Context defragmentation audit
// Analyzes always-loaded files for optimization opportunities

const fs = require('fs');
const path = require('path');

const WORKSPACE = '/root/.openclaw/workspace';
const FILES = [
  'AGENTS.md',
  'TOOLS.md',
  'USER.md',
  'MEMORY.md',
  'HEARTBEAT.md',
  'SOUL.md'
];

function humanSize(bytes) {
  const kb = bytes / 1024;
  return `${kb.toFixed(1)} KB`;
}

function estimateTokens(chars) {
  // Rough estimate: 1 token ≈ 4 characters for English text
  return Math.ceil(chars / 4);
}

function analyzeFile(filePath, content) {
  const lines = content.split('\n');
  const chars = content.length;
  const tokens = estimateTokens(chars);

  const analysis = {
    file: path.basename(filePath),
    chars,
    tokens,
    shouldBeSkill: [],
    outdated: [],
    verbose: [],
    suggestions: []
  };

  // Heuristics for what should be a skill
  if (content.includes('## Memory') && content.includes('decisions, context, things to remember')) {
    analysis.shouldBeSkill.push('Memory maintenance instructions could be a skill');
  }
  if (content.includes('## Tooling') || content.includes('TOOLS.md')) {
    analysis.shouldBeSkill.push('Tool-specific notes could be separate skills');
  }
  if (content.includes('## Health') || content.includes('security audit')) {
    analysis.shouldBeSkill.push('Health check procedures could be a skill');
  }
  if (content.includes('## Heartbeat') && content.includes('check in')) {
    analysis.shouldBeSkill.push('Heartbeat procedures could be a skill');
  }

  // Check for outdated references
  const outdatedPatterns = [
    /v\d+\.\d+\.\d+/g, // version numbers that might be old
    /202[0-6]-\d{2}-\d{2}/g, // old dates
    /deprecated|obsolete|old|previous/gi,
    /TODO|FIXME|XXX/gi
  ];
  outdatedPatterns.forEach(re => {
    const matches = content.match(re);
    if (matches) {
      analysis.outdated.push(...matches.map(m => `"${m}" appears`));
    }
  });

  // Check for verbose sections (long paragraphs, repeated info)
  const longLines = lines.filter(l => l.length > 120 && !l.startsWith('```'));
  if (longLines.length > 0) {
    analysis.verbose.push(`Found ${longLines.length} lines >120 chars that could be wrapped`);
  }

  // Check for redundant "Remember to" or "Don't forget" type instructions
  const imperativeCount = (content.match(/^[A-Z][^.!?]*[.!?]/gm) || []).length;
  if (imperativeCount > 10) {
    analysis.verbose.push(`High imperative count (${imperativeCount}); consider condensing rules`);
  }

  // Suggest moving examples to separate files if file is large
  if (chars > 5000 && content.includes('```')) {
    analysis.suggestions.push('Large file with code examples: consider moving examples to separate reference files');
  }

  return analysis;
}

function runAudit() {
  const results = [];
  let totalCurrent = 0;
  let totalProjected = 0;

  for (const filename of FILES) {
    const filePath = path.join(WORKSPACE, filename);
    if (!fs.existsSync(filePath)) {
      console.log(`⚠️  Missing: ${filename}`);
      continue;
    }
    const content = fs.readFileSync(filePath, 'utf8');
    const analysis = analyzeFile(filePath, content);
    results.push(analysis);
    totalCurrent += analysis.chars;
    // Projected: keep only essential lines, remove verbosity
    const projected = Math.round(analysis.chars * 0.7); // assume 30% reduction
    totalProjected += projected;
  }

  // Summary
  const savings = totalCurrent - totalProjected;
  const tokenSavings = estimateTokens(savings);
  const percent = ((savings / totalCurrent) * 100).toFixed(1);

  return { results, totalCurrent, totalProjected, savings, tokenSavings, percent };
}

const { results, totalCurrent, totalProjected, savings, tokenSavings, percent } = runAudit();

console.log(`# Context Defragmentation Audit\n`);
console.log(`**Current total size:** ${humanSize(totalCurrent)} (${estimateTokens(totalCurrent)} tokens)`);
console.log(`**Projected size:** ${humanSize(totalProjected)} (${estimateTokens(totalProjected)} tokens)`);
console.log(`**Estimated savings:** ${humanSize(savings)} (${tokenSavings} tokens, ${percent}%)\n`);

console.log(`## File-by-File Breakdown\n`);
for (const r of results) {
  console.log(`### ${r.file}`);
  console.log(`- Current: ${humanSize(r.chars)} (${estimateTokens(r.chars)} tokens)`);
  console.log(`- Projected: ~${humanSize(Math.round(r.chars * 0.7))} (${estimateTokens(Math.round(r.chars * 0.7))} tokens)`);
  if (r.shouldBeSkill.length) {
    console.log(`- **Should be a skill:**`);
    r.shouldBeSkill.forEach(s => console.log(`  - ${s}`));
  }
  if (r.outdated.length) {
    console.log(`- **Outdated items:**`);
    r.outdated.slice(0, 5).forEach(o => console.log(`  - ${o}`));
    if (r.outdated.length > 5) console.log(`  - ...and ${r.outdated.length - 5} more`);
  }
  if (r.verbose.length) {
    console.log(`- **Verbosity issues:**`);
    r.verbose.forEach(v => console.log(`  - ${v}`));
  }
  if (r.suggestions.length) {
    console.log(`- **Suggestions:**`);
    r.suggestions.forEach(s => console.log(`  - ${s}`));
  }
  console.log('');
}

console.log(`## Action Items`);
console.log(`1. Move reusable procedures to separate skills (heartbeat, health checks, memory maintenance)`);
console.log(`2. Remove outdated version numbers and deprecated patterns`);
console.log(`3. Condense long paragraphs and reduce imperative statements`);
console.log(`4. Extract large code examples to reference files`);
console.log(`\nRun this skill again after changes to measure improvement.`);

