#!/usr/bin/env node
// RepairShopr API skill for OpenClaw sub-agent
// Reads configuration from MEMORY.md in the agent workspace

const fs = require('fs');
const path = require('path');

// Find MEMORY.md in ancestor directories (agent workspace)
function findMemoryFile() {
  let dir = process.cwd();
  while (dir !== '/') {
    const mem = path.join(dir, 'MEMORY.md');
    if (fs.existsSync(mem)) return mem;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

function parseMemoryForConfig() {
  const memPath = findMemoryFile();
  if (!memPath) throw new Error('MEMORY.md not found');
  const content = fs.readFileSync(memPath, 'utf8');

  const baseUrlMatch = content.match(/\*\*Base URL:\*\*\s*([^\n]+)/i);
  const subdomainMatch = content.match(/\*\*Subdomain:\*\*\s*([^\n]+)/i);
  const apiKeyMatch = content.match(/\*\*API Key:\*\*\s*([^\n]+)/i);

  if (!baseUrlMatch) throw new Error('Base URL not set in MEMORY.md');
  if (!apiKeyMatch) throw new Error('API Key not set in MEMORY.md');

  let baseUrl = baseUrlMatch[1].trim();
  // If base URL contains {subdomain}, replace with actual subdomain
  if (subdomainMatch) {
    const sub = subdomainMatch[1].trim();
    baseUrl = baseUrl.replace('{subdomain}', sub);
  }

  return {
    baseUrl: baseUrl.replace(/\/?$/, ''), // ensure no trailing slash
    apiKey: apiKeyMatch[1].trim()
  };
}

async function fetchJSON(url, options = {}) {
  const res = await fetch(url, {
    headers: {
      'X-Api-Key': config.apiKey,
      'Accept': 'application/json',
      ...(options.headers || {})
    },
    ...options
  });
  if (!res.ok) {
    const text = await res.text();
    let error;
    try { error = JSON.parse(text); } catch { error = { message: text }; }
    throw new Error(`HTTP ${res.status}: ${error.message || res.statusText}`);
  }
  return await res.json();
}

// Tools
const tools = {
  async request({ method, path, body }) {
    const url = `${config.baseUrl}${path}`;
    const opts = { method };
    if (body) {
      opts.headers = { 'Content-Type': 'application/json' };
      opts.body = JSON.stringify(body);
    }
    return await fetchJSON(url, opts);
  },

  async list_tickets({ query, status, page, per_page, comment_format, all_comments }) {
    const params = new URLSearchParams();
    if (query) params.append('query', query);
    if (status) params.append('status', status);
    if (page) params.append('page', page);
    if (per_page) params.append('per_page', per_page);
    if (comment_format) params.append('comment_format', comment_format);
    if (all_comments !== undefined) params.append('all_comments', all_comments);
    const url = `${config.baseUrl}/tickets?${params.toString()}`;
    return await fetchJSON(url);
  },

  async get_ticket({ id }) {
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}`);
  },

  async create_ticket({ subject, customer_id, contact_id, problem_type, ticket_type_id, properties, user_id, priority, due_date, start_at, end_at, asset_ids, comments }) {
    const body = { subject, customer_id, contact_id, problem_type, ticket_type_id, properties, user_id, priority, due_date, start_at, end_at, asset_ids, comments };
    // Remove undefined fields
    Object.keys(body).forEach(k => body[k] === undefined && delete body[k]);
    return await fetchJSON(`${config.baseUrl}/tickets`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  },

  async update_ticket({ id, ...updates }) {
    const body = updates;
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  },

  async delete_ticket({ id }) {
    const res = await fetch(`${config.baseUrl}/tickets/${encodeURIComponent(id)}`, { method: 'DELETE', headers: { 'X-Api-Key': config.apiKey } });
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`HTTP ${res.status}: ${text}`);
    }
    return { message: 'deleted' };
  },

  async get_settings() {
    return await fetchJSON(`${config.baseUrl}/tickets/settings`);
  },

  async list_comments({ id, sort_by, sort_direction, created_after, created_before, updated_after, updated_before, page, per_page, comment_format }) {
    const params = new URLSearchParams();
    if (sort_by) params.append('sort_by', sort_by);
    if (sort_direction) params.append('sort_direction', sort_direction);
    if (created_after) params.append('created_after', created_after);
    if (created_before) params.append('created_before', created_before);
    if (updated_after) params.append('updated_after', updated_after);
    if (updated_before) params.append('updated_before', updated_before);
    if (page) params.append('page', page);
    if (per_page) params.append('per_page', per_page);
    if (comment_format) params.append('comment_format', comment_format);
    const url = `${config.baseUrl}/tickets/${encodeURIComponent(id)}/comments?${params.toString()}`;
    return await fetchJSON(url);
  },

  async add_comment({ id, subject, tech, body, hidden, sms_body, do_not_email }) {
    const bodyData = { subject, tech, body, hidden, sms_body, do_not_email };
    Object.keys(bodyData).forEach(k => bodyData[k] === undefined && delete bodyData[k]);
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/comment`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async create_timer({ id, start_at, end_at, duration_minutes, user_id, notes, product_id }) {
    const bodyData = { start_at, end_at, duration_minutes, user_id, notes, product_id };
    Object.keys(bodyData).forEach(k => bodyData[k] === undefined && delete bodyData[k]);
    return await fetchJSON(`${config.baseURL}/tickets/${encodeURIComponent(id)}/timer_entry`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async add_line_item({ id, name, upc_code, product_id, description, quantity, price_cost, price_retail, taxable }) {
    const bodyData = { name, upc_code, product_id, description, quantity, price_cost, price_retail, taxable };
    Object.keys(bodyData).forEach(k => bodyData[k] === undefined && delete bodyData[k]);
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/add_line_item`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async attach_file_url({ id, url, filename }) {
    const bodyData = { files: [{ url, filename }] };
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/attach_file_url`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async remove_line_item({ id, ticket_line_item_id }) {
    const bodyData = { ticket_line_item_id };
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/remove_line_item`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async update_line_item({ id, ticket_line_item_id, name, upc_code, product_id, description, quantity, price_cost, price_retail, taxable }) {
    const bodyData = { ticket_line_item_id, name, upc_code, product_id, description, quantity, price_cost, price_retail, taxable };
    Object.keys(bodyData).forEach(k => bodyData[k] === undefined && delete bodyData[k]);
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/update_line_item`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async delete_timer({ id, timer_entry_id }) {
    const bodyData = { timer_entry_id };
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/delete_timer_entry`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async update_timer({ id, timer_entry_id, start_at, duration_minutes, user_id, notes, product_id }) {
    const bodyData = { timer_entry_id, start_at, duration_minutes, user_id, notes, product_id };
    Object.keys(bodyData).forEach(k => bodyData[k] === undefined && delete bodyData[k]);
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/update_timer_entry`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  },

  async charge_timer({ id, timer_entry_id }) {
    const bodyData = { timer_entry_id };
    return await fetchJSON(`${config.baseUrl}/tickets/${encodeURIComponent(id)}/charge_timer_entry`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyData) });
  }
};

// Main
let config;
try {
  config = parseMemoryForConfig();
} catch (e) {
  console.error(JSON.stringify({ error: e.message }));
  process.exit(1);
}

(async () => {
  const input = JSON.parse(process.stdin.read());
  const { tool, args } = input;
  if (!tool || !tools[tool]) {
    console.error(JSON.stringify({ error: `Unknown tool: ${tool}` }));
    process.exit(1);
  }
  try {
    const result = await tools[tool](args);
    console.log(JSON.stringify({ result }));
  } catch (err) {
    console.error(JSON.stringify({ error: err.message }));
    process.exit(1);
  }
})();

